using System.Windows;
using CompaterShopWpf.services;
using CompaterShopWpf.Windows;
using SQLitePCL;

namespace CompaterShopWpf.Windows;

public class SignUpModel(Window owner)
{
    public void SignUp(string username, string login, string password)
    {
        if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(login) || string.IsNullOrEmpty(password))
            throw new Exception("Все поля должны быть заполнены");

        try
        {
            if (RegisterService.Register(username, login, password))
            {
                Main mainWindow = new Main();
                mainWindow.Show();
                owner.Close();
            }
        }
        catch (Exception ex)
        {
            throw ex;
        }
    }

    public void OpenSignInWindow()
    {
        SignIn signInWindow = new SignIn();
        signInWindow.Show();
        owner.Close();
    }
    
